-- Only disposable local fixtures; never run against a network database.
do $$begin if current_database()<>'byus_clean' or inet_server_addr() is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.wallet_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.wallet_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:='e9000000-0000-4000-8000-000000000001';other uuid:='e9000000-0000-4000-8000-000000000002';a uuid:='e9000000-0000-4000-8000-000000000010';b uuid:='e9000000-0000-4000-8000-000000000011';pa uuid;pb uuid;key uuid:=extensions.gen_random_uuid();legacy_key uuid:=extensions.gen_random_uuid();source uuid;entry uuid;answer jsonb;prior jsonb;today date:=(clock_timestamp()at time zone'Asia/Seoul')::date;i integer;begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:group-wallet-test','wallet@example.test'),(other,'did:privy:group-wallet-other','wallet-other@example.test');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role)values(a,'group-wallet-a','published','/fixture.webp',now(),'{creator}','creator'),(b,'group-wallet-b','published','/fixture.webp',now(),'{creator}','creator');
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at)values(a,'fixture-v1','exchange','{"free_draw":100,"support_voucher":100}',clock_timestamp())returning id into pa;
 insert into public.mobile_fan_economy_policies(celebrity_id,version,kind,rules,effective_at)values(b,'fixture-v1','exchange','{"free_draw":100,"support_voucher":100}',clock_timestamp())returning id into pb;
 perform public.mobile_fan_economy_post(owner,a,'fan_point',100,'fixture',extensions.gen_random_uuid(),pa);
 perform public.mobile_fan_economy_post(owner,b,'fan_point',200,'fixture',extensions.gen_random_uuid(),pb);
 perform public.mobile_fan_economy_post(owner,a,'paid_vote',3,'fixture',extensions.gen_random_uuid(),pa);
 perform public.mobile_fan_economy_post(owner,a,'free_vote',4,'fixture',extensions.gen_random_uuid(),pa);
 prior:=public.post_fan_ticket_entry(owner,a,'credit',2,'fixture',a,legacy_key,2);
 perform public.post_fan_ticket_entry(owner,b,'credit',3,'fixture',b,extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.get_fan_ticket_balance(owner,a)=2 and public.get_fan_ticket_balance(owner,b)=3,'disabled release retains legacy creator balances');
 perform pg_temp.wallet_error(format('select public.read_owned_group_wallet(%L)',owner),'UNAVAILABLE');
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=today;
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'fan_point')=300 and public.group_wallet_balance(owner,'ticket')=5,'legacy free balances project once without copying rows');
 perform pg_temp.wallet_assert(public.mobile_fan_economy_balance(owner,b,'fan_point')=300 and public.get_fan_ticket_balance(owner,a)=5,'legacy readers use same global free balance');
 perform pg_temp.wallet_assert(public.post_fan_ticket_entry(owner,a,'credit',2,'fixture',a,legacy_key,2)=prior||'{"replayed":true}'::jsonb,'old receipt replay preserves original creator and resulting balance');
 answer:=public.exchange_owned_group_wallet(owner,key,'group-wallet-v1','heart',1);
 perform pg_temp.wallet_assert(public.exchange_owned_group_wallet(owner,key,'group-wallet-v1','heart',1)=answer||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'fan_point')=200 and public.group_wallet_balance(owner,'support_voucher')=1,'heart exchange atomic and replay-safe');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1)',owner,key),'REQUEST_CONFLICT');
 perform public.exchange_owned_group_wallet(owner,extensions.gen_random_uuid(),'group-wallet-v1','ticket',2);
 perform public.post_fan_ticket_entry(owner,a,'debit',-4,'fixture_debit',extensions.gen_random_uuid(),extensions.gen_random_uuid(),2);
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3 and public.get_fan_ticket_balance(owner,b)=3,'legacy debit consumes same tickets as global exchange');
 perform pg_temp.wallet_error(format('select public.group_wallet_post(%L,''ticket'',-4,''group_capsule'',%L)',owner,extensions.gen_random_uuid()),'INSUFFICIENT_BALANCE');
 perform pg_temp.wallet_assert(public.group_wallet_balance(owner,'ticket')=3,'failed debit does not spend');
 perform pg_temp.wallet_assert(public.mobile_fan_economy_balance(owner,a,'paid_vote')=3 and public.mobile_fan_economy_balance(owner,b,'paid_vote')=0 and public.mobile_fan_economy_balance(owner,a,'free_vote')=4,'paid rights and vote assets retain creator scope');
 for i in 1..6 loop
  source:=extensions.gen_random_uuid();entry:=public.group_wallet_post(owner,'fan_point',10,'group_check_in',source);
  insert into public.group_wallet_attendance values(owner,today-7+i,i,10,entry);
 end loop;
 key:=extensions.gen_random_uuid();answer:=public.check_in_owned_group_wallet(owner,key);
 perform pg_temp.wallet_assert(answer->>'pointsAwarded'='30'and answer->>'streak'='7','seventh consecutive day awards 10 plus 20');
 perform public.check_in_owned_group_wallet(owner,key);perform public.check_in_owned_group_wallet(owner,extensions.gen_random_uuid());
 perform pg_temp.wallet_assert((select count(*)from public.group_wallet_attendance where app_user_id=owner and attendance_date=today)=1 and public.group_wallet_balance(owner,'fan_point')=90,'same date and key award exactly once');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(other,key)->>'status'='unknown','receipt ownership isolated');
 perform pg_temp.wallet_assert(not exists(select 1 from public.community_stamps where app_user_id=owner)and not exists(select 1 from public.fan_score_ledger where app_user_id=owner),'global points do not mint creator stamps or change XP');
 key:=extensions.gen_random_uuid();answer:=public.send_owned_group_wallet_support(owner,key,'group-wallet-v1','group-wallet-b',1);
 perform pg_temp.wallet_assert(public.send_owned_group_wallet_support(owner,key,'group-wallet-v1','group-wallet-b',1)=answer||'{"replayed":true}'::jsonb and public.group_wallet_balance(owner,'support_voucher')=0 and(select count(*)from public.mobile_fan_support_contributions where app_user_id=owner and request_key=key)=1,'global heart send preserves original contribution FK and replays once');
 perform pg_temp.wallet_assert(not exists(select 1 from public.mobile_fan_economy_policies where celebrity_id=b and version='group-wallet-support-v1'and retired_at is null),'global send audit policy never replaces active creator policy');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(owner,legacy_key)->>'status'='legacy','old transaction is not mislabeled unknown');
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1)',owner,legacy_key),'REQUEST_CONFLICT');
 source:=extensions.gen_random_uuid();insert into public.mobile_fan_economy_cancellations values(owner,source,'exchange','{}',clock_timestamp());
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''heart'',1)',owner,source),'REQUEST_CONFLICT');
 source:=extensions.gen_random_uuid();entry:=public.group_wallet_post(other,'fan_point',130,'group_check_in',source);
 insert into public.group_wallet_attendance values(other,today-1,13,10,entry);
 answer:=public.check_in_owned_group_wallet(other,extensions.gen_random_uuid());
 perform pg_temp.wallet_assert(answer->>'pointsAwarded'='30'and answer->>'streak'='14','every seventh day awards again, not once per account');
 perform pg_temp.wallet_assert(public.award_mobile_fan_activity(owner,a,'checkin',today::text)->>'status'='not_eligible'and public.award_mobile_fan_activity(owner,b,'checkin',today::text)->>'status'='not_eligible'and public.group_wallet_balance(owner,'fan_point')=90,'legacy creator check-ins cannot duplicate global daily point producer');
 key:=extensions.gen_random_uuid();perform public.check_in_owned_group_wallet(owner,key);
 update public.group_wallet_release set write_fenced=true;
 perform pg_temp.wallet_error(format('select public.exchange_owned_group_wallet(%L,%L,''group-wallet-v1'',''ticket'',1)',owner,extensions.gen_random_uuid()),'WRITE_FENCED');
 perform pg_temp.wallet_error(format('select public.post_fan_ticket_entry(%L,%L,''credit'',1,''fenced'',%L,%L,2)',owner,a,extensions.gen_random_uuid(),extensions.gen_random_uuid()),'WRITE_FENCED');
 perform pg_temp.wallet_assert(public.read_owned_group_wallet_request(owner,key)->>'status'='committed','fence preserves committed request recovery');
 perform pg_temp.wallet_assert(not has_table_privilege('service_role','public.group_wallet_release','UPDATE')and not has_function_privilege('authenticated','public.exchange_owned_group_wallet(uuid,uuid,text,text,integer)','EXECUTE'),'activation and currency writer not client-writable');
end $$;
rollback;
